// H1 heading with back button using browser history
import { useRouter } from 'next/navigation';

function PageWithBackButton() {
  const router = useRouter();
  return (
    <Heading 
      level="h1" 
      onBackClick={() => router.back()}
      backLinkTitle="Go back"
      showBar={false}
    >
      Detail Page
    </Heading>
  );
}
