// Editable H2 heading
import { useState } from 'react';

function EditableHeadingExample() {
  const [title, setTitle] = useState('Click to edit me');

  return (
    <Heading 
      level="h2" 
      editable={true} 
      onEditSave={setTitle}
    >
      {title}
    </Heading>
  );
}
